from pathlib import Path
p=Path('tokeneconomizer/trace/codex.py')
s=p.read_text(encoding='utf8')
s=s.replace('events, converted as \`te_harness.codex.row_usage\` converts the exec stream\\'s,\\nbecause Codex\\'s \`input_tokens\` is the GRAND input total including both cache fields.', 'events. Codex input includes both cache fields, and output includes reasoning.')
s=s.replace('import shlex\\n','import shlex\\nfrom pathlib import Path\\n')
s=s[:s.index('def codex_session_usage(')]+'''_COUNTERS = ("input_tokens", "cached_input_tokens", "cache_write_input_tokens",
             "output_tokens", "reasoning_output_tokens")
_LEDGER_FIELDS = ("input_tokens", "cache_read_input_tokens", "cache_creation_input_tokens",
                  "output_tokens", "reasoning_output_tokens")


def _counter(row):
    if not isinstance(row, dict):
        raise ValueError("invalid usage record")
    # Cache writes are absent on hosts that do not report them. Reasoning is diagnostic.
    values = tuple(row.get(key, 0 if i in (2, 4) else None)
                   for i, key in enumerate(_COUNTERS))
    if (any(type(n) is not int or n < 0 for n in values)
            or values[1] + values[2] > values[0] or values[4] > values[3]):
        raise ValueError("invalid usage counter")
    return values


def _rollout_usage(path):
    """Read one segment, preserving read/parse errors and its usage event identities."""
    model = None
    events = []
    previous = None
    snapshot = None
    saw_rollout = False
    reasoning_reported = True
    if not path:
        return "transcript_missing", model, events, reasoning_reported
    path = Path(path)
    try:
        with path.open(encoding="utf-8-sig") as stream:
            if path.suffix.lower() != ".jsonl":
                return "transcript_unsupported", model, events, reasoning_reported
            for line in stream:
                if not line.strip():
                    continue
                record = json.loads(line)
                if not isinstance(record, dict):
                    return "transcript_invalid", model, events, reasoning_reported
                payload = record.get("payload")
                kind = record.get("type")
                if isinstance(payload, dict) and kind in (
                        "session_meta", "turn_context", "event_msg", "response_item", "compacted"):
                    saw_rollout = True
                else:
                    continue
                if kind == "turn_context":
                    model = payload.get("model") or model
                if kind != "event_msg" or payload.get("type") != "token_count":
                    continue
                info = payload.get("info")
                if info is None:  # Codex also publishes rate-limit-only events.
                    continue
                if not isinstance(info, dict):
                    return "incomplete_usage", model, events, reasoning_reported
                total_row = info.get("total_token_usage")
                last_row = info.get("last_token_usage")
                if total_row is None and last_row is None:
                    return "incomplete_usage", model, events, reasoning_reported
                try:
                    total = _counter(total_row) if total_row is not None else None
                    last = _counter(last_row) if last_row is not None else None
                    if total is not None and total == snapshot:
                        continue
                    if total is None:
                        # Advance the expected cumulative baseline to avoid counting this call
                        # again when a later event supplies cumulative usage.
                        if previous is not None:
                            previous = tuple(a + b for a, b in zip(previous, last))
                    else:
                        if previous is None:
                            if last is None or any(a < b for a, b in zip(total, last)):
                                raise ValueError("unbounded baseline")
                        else:
                            delta = tuple(a - b for a, b in zip(total, previous))
                            if any(n < 0 for n in delta):
                                if last != total:
                                    raise ValueError("unbounded reset")
                            else:
                                delta = _counter(dict(zip(_COUNTERS, delta)))
                                if last is not None and last != delta:
                                    raise ValueError("counter mismatch")
                                last = delta
                        snapshot = previous = total
                    reasoning_reported &= all(_COUNTERS[-1] in row for row in
                                              (total_row, last_row) if row is not None)
                except ValueError:
                    return "incomplete_usage", model, events, reasoning_reported
                if any(last):
                    events.append((record.get("timestamp"), total, last))
    except FileNotFoundError:
        return "transcript_missing", model, events, reasoning_reported
    except OSError:
        return "transcript_access_error", model, events, reasoning_reported
    except (ValueError, UnicodeError):
        return "transcript_invalid", model, events, reasoning_reported
    status = "ok" if events else "no_usage" if saw_rollout else "transcript_invalid"
    return status, model, events, reasoning_reported


def codex_session_segments(paths):
    """Account for disjoint segments or exact copies. Refuse ambiguous overlaps."""
    segments = []
    model = None
    status = "transcript_missing"
    for path in paths:
        status, segment_model, events, reasoning_reported = _rollout_usage(path)
        model = segment_model or model
        if status != "ok":
            break
        if not any(events == prior[0] for prior in segments):
            segments.append((events, segment_model, reasoning_reported))
    if status == "ok" and len(segments) > 1:
        spans = []
        for events, segment_model, _ in segments:
            stamps = [event[0] for event in events]
            if not all(isinstance(stamp, str) and stamp.endswith("Z") for stamp in stamps):
                status = "ambiguous_segments"
                break
            spans.append((min(stamps), max(stamps), segment_model))
        spans.sort(key=lambda span: span[0])
        if (any(a[1] >= b[0] for a, b in zip(spans, spans[1:]))
                or len({span[2] for span in spans if span[2]}) > 1):
            status = "ambiguous_segments"
    result = dict.fromkeys(_LEDGER_FIELDS)
    result.update(model=model, requests=None, usage_status=status)
    if status == "ok":
        usages = [last for events, _, _ in segments for _, _, last in events]
        result.update(zip(_LEDGER_FIELDS, map(sum, zip(*usages))))
        result["input_tokens"] -= result["cache_read_input_tokens"]
        result["input_tokens"] -= result["cache_creation_input_tokens"]
        if not all(known for _, _, known in segments):
            result["reasoning_output_tokens"] = None
        result["requests"] = len(usages)
    elif status == "no_usage":
        result["requests"] = 0
    return result


def codex_session_usage(rollout_path):
    """Account for a single rollout using attributable requests and cumulative deltas."""
    return codex_session_segments([rollout_path])
